import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatSelectModule } from '@angular/material/select';
import { IconComponent } from '../../icon/icon.component';
import { AvatarComponent } from '../../avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { FiltersMDL } from '../../../interfaces/filter.interface';
import { selectedContactList } from '../../../interfaces/issue.interface';
import { ContactService } from '../../../services/contact/contact.service';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'contacts',
  standalone: true,
  imports: [MatSelectModule, FormsModule, IconComponent, AvatarComponent, MatTooltipModule],
  templateUrl: './contacts.component.html',
  styleUrl: './contacts.component.scss'
})
export class ContactsComponent {
  selected: any;
  @Input() filterData: FiltersMDL = {} as FiltersMDL;
  @Input() nCaseid: string;
  isMessage: boolean = true;

  // d
  contactList: selectedContactList[] = [];
  @Output() OnValueUpdate = new EventEmitter<toolEvents>();
  constructor(private contactService: ContactService) {
  }

  async ngOnInit() {
    this.contactList = await this.contactService.getContactList(this.nCaseid);
  }



  OnSelect(e: any) {
    if (e.value.includes(0)) {
      this.selected = [...this.contactList];
    }
    this.updateValue();
  }

  updateValue() {
    this.filterData.value = this.selected.map(a => a.nContactid);
    this.OnValueUpdate.emit({event:"CONTACT", data: ''});
  }

  remove(i: number) {
    this.selected.splice(i, 1);
    this.selected = [...this.selected]
    this.updateValue();
  }
}
