  constructor(private http: HttpClient) { }


  async checkNavData(nBundledetailid: string): Promise<checkNavRes> {
    const params = new HttpParams().set('nBundledetailid', nBundledetailid);
    let res: any = {};
    try {
      res = await firstValueFrom(
        this.http.get<checkNavRes>(
          `${environment.cloudUrl}${environment.coreservice}/navigation/checknavigationdata`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = {} as checkNavRes;
    }
    return res;
  }


