import { ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { DocInfo, toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { FiltersMDL } from '../../../interfaces/filter.interface';
import { NavigateService } from '../../../../userpanel/services/navigate/navigate.service';
import { MatTooltipModule } from '@angular/material/tooltip';
import { AvatarComponent } from '../../avatar/avatar.component';
import { IconComponent } from '../../icon/icon.component';
import { FormsModule } from '@angular/forms';
import { MatSelectModule } from '@angular/material/select';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'destination',
  standalone: true,
  imports: [CommonModule,MatSelectModule, FormsModule, IconComponent, AvatarComponent, MatTooltipModule],
  templateUrl: './destination.component.html',
  styleUrl: './destination.component.scss'
})
export class DestinationComponent {

  selected: any;
  @Input() filterData: FiltersMDL = {} as FiltersMDL;
  @Output() OnValueUpdate = new EventEmitter<toolEvents>();
  @Input() docInfo: DocInfo = {} as DocInfo;
  @Input() nCaseid: string;
  isMessage: boolean = true;


  filelinks: DocInfo[] = [];


  
  constructor(private navService: NavigateService, private cdr: ChangeDetectorRef) { }



  async ngOnInit() {
    
      this.filelinks = await this.navService.getDestinationFilters(this.docInfo.nBundledetailid);
  }

  OnSelect(e: any) {
    if (e.value.includes(0)) {
      this.selected = [...this.filelinks];
    }
    this.updateValue();
  }

  updateValue() {
    this.filterData.value = this.selected.map(a => a.nDMLids);
    this.OnValueUpdate.emit({ event: 'DESTINATION', data: '' });
  }

  remove(i: number) {
    this.selected.splice(i, 1);
    this.selected = [...this.selected]
    this.updateValue();
  }

}
