import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatSelectModule } from '@angular/material/select';
import { IconComponent } from '../../icon/icon.component';
import { DatepickerComponent } from '../../datepicker/datepicker.component';
import { FiltersMDL } from '../../../interfaces/filter.interface';
import moment from 'moment';
import { CommonService } from '../../../services/common/common.service';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'date',
  standalone: true,
  imports: [MatSelectModule, FormsModule, IconComponent, DatepickerComponent],
  templateUrl: './date.component.html',
  styleUrl: './date.component.scss'
})
export class DateComponent {
  selected: any;
  @Input() filterData: FiltersMDL = {} as FiltersMDL;
  @Input() nCaseid: string;
  isMessage: boolean = true
  datelist: any[] = [
    {
      cKey: 'Today',
      dStartdt: this.cf.getDateFormate(moment().startOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ'),
      dEnddt: this.cf.getDateFormate(moment().endOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ')
    },
    {
      cKey: 'One week',
      dStartdt: this.cf.getDateFormate(moment().subtract(1, 'week').startOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ'),
      dEnddt: this.cf.getDateFormate(moment().endOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ'),
    },
    {
      cKey: 'One month',
      dStartdt: this.cf.getDateFormate(moment().subtract(1, 'month').startOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ'),
      dEnddt: this.cf.getDateFormate(moment().endOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ'),
    },
    {
      cKey: 'Custom',
      dStartdt: this.cf.getDateFormate(moment().subtract(1, 'month').startOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ'),
      dEnddt: this.cf.getDateFormate(moment().endOf('day').toDate(), 'YYYY-MM-DDTHH:mm:ssZ'),
    }
  ];


  @Output() OnValueUpdate = new EventEmitter<toolEvents>();
  constructor(private common: CommonService, private cf: CommonfunctionService) {

  }


  OnSelect(e: any) {
    this.updateValue();
  }

  updateValue() {
    this.filterData.value = { startDt: this.selected?.dStartdt, endDt: this.selected?.dEnddt };
    this.OnValueUpdate.emit({ event: "DATE", data: '' });
  }

  remove() {
    this.selected = null;
    this.updateValue();
  }


  OnDateChange(e: any, x, column: string) {
    x[column] = moment(new Date(e)).format('YYYY-MM-DDTHH:mm:ssZ');
    this.updateValue();
  }

  onOptionClick(event: MouseEvent): void {
    event.stopPropagation();
    this.selected = this.datelist.find(a => a.cKey == 'Custom');
  }

}
