import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatSelectModule } from '@angular/material/select';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { ButtonComponent } from '../../button/button.component';
import { FiltersMDL } from '../../../interfaces/filter.interface';
import { CommonService } from '../../../services/common/common.service';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'task',
  standalone: true,
  imports: [MatSelectModule, FormsModule, IconComponent, CommonModule, ButtonComponent],
  templateUrl: './task.component.html',
  styleUrl: './task.component.scss'
})
export class TaskComponent {
  selected: any = [];
  @Input() filterData: FiltersMDL = {} as FiltersMDL;
  @Input() nCaseid: string;
  isMessage: boolean = true
  gropuList: any = [
    {
      cCategory: "Priority",
      sublist: []
    },
    {
      cCategory: "Progress",
      sublist: [
        {
          cKey: "Completed",
          cValue: 'C'
        },
        {
          cKey: "In progress",
          cValue: 'P'
        },
        {
          cKey: "Not yet started",
          cValue: 'N'
        }
      ]
    },
    {
      cCategory: "Timeline",
      sublist: [
        {
          cKey: "One day",
          cValue: "1"
        },
        {
          cKey: "Two days",
          cValue: "2"
        },
        {
          cKey: "Custom",
          cValue: "3"
        }
      ]
    }
  ]

  @Output() OnValueUpdate = new EventEmitter<toolEvents>();
  constructor(private common: CommonService) {

  }

  async ngOnInit() {
    const priority = await this.common.getCode(17);
    this.gropuList[0]["sublist"] = priority;

  }

  customDay(y) {
    debugger
    this.selected = this.selected && this.selected.length ? this.selected : [];
    let ind = this.selected.findIndex(e => e.cKey == y.cKey)
    if (ind >= -1) {
      if (y.cValue && y.cValue != '') {
        this.selected.push(y);
      }
    } else {
      this.selected[ind].cValue = y.cValue
      if (!y.cValue || y.cValue == '') {
        this.selected.splice(ind, 1)
      }
    }
    this.updateValue();
  }

  OnSelect(e: any) {
    debugger;
    if (e.value.includes(0)) {
      this.selected = [...this.gropuList.flatMap(a => a.sublist)];
    }

    this.updateValue();
  }



  updateValue() {
    let selectedValues = [];
    // this.filterData.value = this.selected.map(a => a.nValue);
    if (this.selected.length) {
      selectedValues = this.gropuList.map(a => { return { key: a.cCategory, value: a.sublist.filter(e => this.selected.some(x => x.cKey === e.cKey)) } })
    }

    this.filterData.value = selectedValues.reduce((acc, curr) => {
      const key = curr.key === 'Priority' ? 'jPriority' : curr.key === 'Progress' ? 'jProgress' : curr.key;
      acc[key] = curr.value.map((v: any) => v.nValue || v.cValue);
      return acc;
    }, {} as Record<string, any>);

    // this.filterData.value = { jPriority: this.selected.map(a => a.nValue) }
    this.OnValueUpdate.emit({ event: "DATE", data: '' });
  }

  remove(i: number) {
    this.selected.splice(i, 1);
    this.selected = [...this.selected]
    this.updateValue();
  }

}
