import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { ChangeDetectionStrategy, Component, Input, Output, EventEmitter, OnChanges } from '@angular/core';
import { IconComponent } from '../icon/icon.component';
import { filterItemType, FILTER_ITEM, FILTER_LIST } from '../../interfaces/mark-nav-filter.interface';
import { FiltersMDL, FILTER_TYPE, FILTER_KEYS } from '../../interfaces/filter.interface';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ClaimsComponent } from '../nav-filters/filter-components/claims/claims.component';
import { FactdetailfilterComponent } from '../nav-filters/filter-components/factdetailfilter/factdetailfilter.component';
import { FactcontactfilterComponent } from '../nav-filters/filter-components/factcontactfilter/factcontactfilter.component';
import { FacttaskfilterComponent } from '../nav-filters/filter-components/facttaskfilter/facttaskfilter.component';
import { SelectedfilterComponent } from './selectedfilter/selectedfilter.component';
import { IssuesComponent } from '../nav-filters/filter-components/issues/issues.component';
import { TypesComponent } from "./types/types.component";
import { RelavanceComponent } from './relavance/relavance.component';
import { ImpactComponent } from './impact/impact.component';
import { StatusComponent } from './status/status.component';
import { LinkComponent } from './link/link.component';
import { DateComponent } from './date/date.component';
import { TaskComponent } from './task/task.component';
import { ContactsComponent } from './contacts/contacts.component';
import { LinktypeComponent } from './linktype/linktype.component';
import { DestinationComponent } from './destination/destination.component';
import { FileinfoComponent } from './fileinfo/fileinfo.component';
import { WebfilterComponent } from './webfilter/webfilter.component';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { CreatorComponent } from './creator/creator.component';
import { AssigneeComponent } from './assignee/assignee.component';
import { TranslateModule } from '@ngx-translate/core';
import { ButtonComponent } from '../button/button.component';
import { MatMenuModule } from '@angular/material/menu';

@Component({
  selector: 'filters',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    IconComponent, MatSelectModule, FormsModule, CommonModule, ClaimsComponent, SelectedfilterComponent, IssuesComponent, TypesComponent,
    RelavanceComponent, ImpactComponent, StatusComponent, ContactsComponent, LinkComponent, DateComponent, TaskComponent, LinktypeComponent,
    DestinationComponent, FileinfoComponent, WebfilterComponent, NgScrollbarModule, CreatorComponent, AssigneeComponent, TranslateModule,
    ButtonComponent, MatMenuModule, FactdetailfilterComponent, FactcontactfilterComponent, FacttaskfilterComponent
  ],
  templateUrl: './filters.component.html',
  styleUrls: ['./filters.component.scss']
})
export class FiltersComponent implements OnChanges {
  readonly FILTER_ITEM = FILTER_ITEM;
  originalFilters: any = null;
  constructor(private readonly secureStorage: SecureStorageService) {
    // If nUserid is not provided as input, try to get it from storage
    if (!this.nUserid) {
      this.nUserid = this.secureStorage.userInfo?.nUserid;
    }
    this.backupCurrentState();
  }
  claimFilterData: FiltersMDL = { type: FILTER_TYPE.CLAIM, value: [], consition: 'OR' };
  @Output() OnFilter = new EventEmitter<any>();
  @Input() nCaseid: string;
  @Input() nUserid: string;
  @Input() tab: any; // Accept any type for now
  @Input() selectedTab: string;
  @Input() contactFilter: any;
  @Input() nViewissueid: number;
  @Input() selectedMode: string;
  @Input() isAdvance: boolean;
  @Input() docInfo: any;
  @Input() onNavigateEvent: any;

  ngOnChanges(changes: any) {
    // Backup state on input changes
    this.backupCurrentState();
  }

  filters = FILTER_LIST;

  selectedFilters: filterItemType[] = [];
  jClaims: string[] = [];
  jIssues: string[] = [];
  jRels: number[] = [];
  jImps: number[] = [];
  jDate: any = null;
  jFiletypes: number[] = [];
  jLevels: any = null;
  jFilters: any = null;
  jStatus: number[] = [];
  createDate: { start: string, end: string } = { start: '', end: '' };
  createBy: string[] = [];
  jContacts: string[] = [];
  jCRoles: string[] = [];
  jCPartys: number[] = [];
  jCCompanies: string[] = [];
  IsContactNote: boolean = false;
  jTasks: string[] = [];
  IsTaskDesc: boolean = false;
  jTShared: string[] = [];
  jTStatus: number[] = [];
  jTPriority: number[] = [];
  dTDate: any = null;
  IsNote: boolean = false;
  IsFactlink: boolean = false;
  IsComment: boolean = false;
  trackByFilterOption(index: number, item: any): any {
    return item.value;
  }

  addfilter(x: any) {
    const idx = this.selectedFilters.indexOf(x.value);
    if (idx > -1) {
      this.selectedFilters.splice(idx, 1);
    } else {
      this.selectedFilters.push(x.value);
    }
  }

  emitFilterEvent(event: string, data: any = null) {
    this.OnFilter.emit({ event, data });
  }

  saveFilter(apply: boolean) {
    const jFilters = this.buildJFilters();
    this.cleanJFilters(jFilters);
    const filterArray = this.buildFilterArray(jFilters);
    this.emitFilterEvent('FILTER', filterArray);
    this.backupCurrentState();
  }

  private buildJFilters(): any {
    const jFilters: any = {};
    this.addClaimJFilters(jFilters);
    this.addIssueJFilters(jFilters);
    this.addFactJFilters(jFilters);
    this.addQFJFilters(jFilters);
    this.addTypeJFilters(jFilters);
    this.addContactJFilters(jFilters);
    this.addTaskJFilters(jFilters);
    return jFilters;
  }

  private addClaimJFilters(jFilters: any) {
    if (this.jClaims?.length) jFilters.jClaims = this.jClaims;
  }

  private addIssueJFilters(jFilters: any) {
    if (this.jIssues?.length) jFilters.jIssues = this.jIssues;
    if (this.jRels?.length) jFilters.jRels = this.jRels;
    if (this.jImps?.length) jFilters.jImps = this.jImps;
    if (this.IsNote) jFilters.IsNote = this.IsNote;
    if (this.IsFactlink) jFilters.IsFactlink = this.IsFactlink;
    if (this.IsComment) jFilters.IsComment = this.IsComment;
  }

  private addFactJFilters(jFilters: any) {
    if (this.jDate) jFilters.jDate = this.jDate;
    if (this.jFiletypes?.length) jFilters.jFiletypes = this.jFiletypes;
    if (this.jStatus?.length) jFilters.jStatus = this.jStatus;
  }

  private addQFJFilters(jFilters: any) {
    if (this.selectedFilters.includes(this.FILTER_ITEM.QF)) {
      if (this.createDate) jFilters.createDate = this.createDate;
      if (this.createBy?.length) jFilters.createBy = this.createBy;
    }
  }

  private addTypeJFilters(jFilters: any) {
    if (this.jLevels) jFilters.cType = this.jLevels;
  }

  private addContactJFilters(jFilters: any) {
    if (this.selectedFilters.includes(this.FILTER_ITEM.C)) {
      if (this.jContacts?.length) jFilters.jContacts = this.jContacts;
      if (this.jCRoles?.length) jFilters.jCRoles = this.jCRoles;
      if (this.jCPartys?.length) jFilters.jCPartys = this.jCPartys;
      if (this.jCCompanies?.length) jFilters.jCCompanies = this.jCCompanies;
      if (this.IsContactNote) jFilters.IsContactNote = this.IsContactNote;
    }
  }

  private addTaskJFilters(jFilters: any) {
    if (this.selectedFilters.includes(this.FILTER_ITEM.T)) {
      if (this.jTasks?.length) jFilters.jTasks = this.jTasks;
      if (this.IsTaskDesc) jFilters.IsTaskDesc = this.IsTaskDesc;
      if (this.jTShared?.length) jFilters.jTShared = this.jTShared;
      if (this.jTStatus?.length) jFilters.jTStatus = this.jTStatus;
      if (this.jTPriority?.length) jFilters.jTPriority = this.jTPriority;
      if (this.dTDate) jFilters.dTDate = this.dTDate;
    }
  }

  private cleanJFilters(jFilters: any): void {
    Object.keys(jFilters).forEach(key => {
      if (Array.isArray(jFilters[key]) && !jFilters[key].length) delete jFilters[key];
      if (jFilters[key] === undefined || jFilters[key] === null) delete jFilters[key];
    });
  }

  private buildFilterArray(jFilters: any): any[] {
    let filterArray: any[] = [];
    filterArray = filterArray.concat(this.getClaimFilters(jFilters));
    filterArray = filterArray.concat(this.getIssueFilters(jFilters));
    filterArray = filterArray.concat(this.getFactFilters(jFilters));
    filterArray = filterArray.concat(this.getQFFilters(jFilters));
    filterArray = filterArray.concat(this.getTypeFilters(jFilters));
    filterArray = filterArray.concat(this.getContactFilters(jFilters));
    filterArray = filterArray.concat(this.getTaskFilters(jFilters));
    return filterArray;
  }

  private getClaimFilters(jFilters: any): any[] {
    return jFilters.jClaims?.length ? [{ name: FILTER_KEYS.CLAIM, type: 'V', value: jFilters.jClaims }] : [];
  }

  private getIssueFilters(jFilters: any): any[] {
    const arr = [];
    if (jFilters.jIssues?.length) arr.push({ name: FILTER_KEYS.ISSUE, type: 'V', value: jFilters.jIssues });
    if (jFilters.jRels?.length) arr.push({ name: FILTER_KEYS.RELEVANCE, type: 'V', value: jFilters.jRels });
    if (jFilters.jImps?.length) arr.push({ name: FILTER_KEYS.IMPACT, type: 'V', value: jFilters.jImps });
    if (jFilters.IsNote) arr.push({ name: FILTER_KEYS.ISNOTE, type: 'V', value: jFilters.IsNote });
    if (jFilters.IsFactlink) arr.push({ name: FILTER_KEYS.ISFACTLINK, type: 'V', value: jFilters.IsFactlink });
    if (jFilters.IsComment) arr.push({ name: FILTER_KEYS.ISCOMMENT, type: 'V', value: jFilters.IsComment });
    return arr;
  }

  private getFactFilters(jFilters: any): any[] {
    const arr = [];
    if (jFilters.jDate && Object.keys(jFilters.jDate).length) arr.push({ name: FILTER_KEYS.DATE, type: 'V', value: jFilters.jDate });
    if (jFilters.jFiletypes?.length) arr.push({ name: FILTER_KEYS.FILETYPE, type: 'V', value: jFilters.jFiletypes });
    if (jFilters.jStatus?.length) arr.push({ name: FILTER_KEYS.STATUS, type: 'V', value: jFilters.jStatus });
    return arr;
  }

  private getQFFilters(jFilters: any): any[] {
    const arr = [];
    if (jFilters.createDate && Object.keys(jFilters.createDate).length) arr.push({ name: FILTER_KEYS.CREATEDATE, type: 'V', value: jFilters.createDate });
    if (jFilters.createBy?.length) arr.push({ name: FILTER_KEYS.CREATOR, type: 'V', value: jFilters.createBy });
    return arr;
  }

  private getTypeFilters(jFilters: any): any[] {
    return jFilters.cType ? [{ name: FILTER_KEYS.CTYPE, type: 'V', value: jFilters.cType }] : [];
  }

  private getContactFilters(jFilters: any): any[] {
    const arr = [];
    if (jFilters.jContacts?.length) arr.push({ name: FILTER_KEYS.CONTACT, type: 'V', value: jFilters.jContacts });
    if (jFilters.jCRoles?.length) arr.push({ name: FILTER_KEYS.CROLE, type: 'V', value: jFilters.jCRoles });
    if (jFilters.jCPartys?.length) arr.push({ name: FILTER_KEYS.CPARTY, type: 'V', value: jFilters.jCPartys });
    if (jFilters.jCCompanies?.length) arr.push({ name: FILTER_KEYS.CCOMPANY, type: 'V', value: jFilters.jCCompanies });
    if (jFilters.IsContactNote) arr.push({ name: FILTER_KEYS.ISCONTACTNOTE, type: 'V', value: jFilters.IsContactNote });
    return arr;
  }

  private getTaskFilters(jFilters: any): any[] {
    const arr = [];
    if (jFilters.jTasks?.length) arr.push({ name: FILTER_KEYS.TASK, type: 'V', value: jFilters.jTasks });
    if (jFilters.IsTaskDesc) arr.push({ name: FILTER_KEYS.ISTASKDESC, type: 'V', value: jFilters.IsTaskDesc });
    if (jFilters.jTShared?.length) arr.push({ name: FILTER_KEYS.TSHARED, type: 'V', value: jFilters.jTShared });
    if (jFilters.jTStatus?.length) arr.push({ name: FILTER_KEYS.TSTATUS, type: 'V', value: jFilters.jTStatus });
    if (jFilters.jTPriority?.length) arr.push({ name: FILTER_KEYS.TPRIORITY, type: 'V', value: jFilters.jTPriority });
    if (jFilters.dTDate) arr.push({ name: FILTER_KEYS.TDATE, type: 'V', value: jFilters.dTDate });
    return arr;
  }

  private addClaimFilters(jFilters: any) {
    if (this.selectedFilters.includes(this.FILTER_ITEM.CL) && this.jClaims?.length) {
      jFilters.jClaims = this.jClaims;
    }
  }

  private addIssueFilters(jFilters: any) {
    if (this.selectedFilters.includes(this.FILTER_ITEM.I)) {
      if (this.jIssues?.length) jFilters.jIssues = this.jIssues;
      if (this.jRels?.length) jFilters.jRels = this.jRels;
      if (this.jImps?.length) jFilters.jImps = this.jImps;
      if (this.IsNote) jFilters.IsNote = this.IsNote;
      if (this.IsFactlink) jFilters.IsFactlink = this.IsFactlink;
      if (this.IsComment) jFilters.IsComment = this.IsComment;
    }
  }

  cancelFilter() {
    // Restore previous state if available and signal parent to close the filter window
    if (this.originalFilters) {
      this.selectedFilters = [...this.originalFilters.selectedFilters];
      this.jClaims = [...this.originalFilters.jClaims];
      this.jIssues = [...this.originalFilters.jIssues];
      this.jRels = [...this.originalFilters.jRels];
      this.jImps = [...this.originalFilters.jImps];
      this.jDate = this.originalFilters.jDate ? { ...this.originalFilters.jDate } : null;
      this.jFiletypes = [...this.originalFilters.jFiletypes];
      this.jLevels = this.originalFilters.jLevels;
      this.jFilters = this.originalFilters.jFilters;
      this.jStatus = [...this.originalFilters.jStatus];
      this.createDate = this.originalFilters.createDate ? { ...this.originalFilters.createDate } : { start: '', end: '' };
      this.createBy = [...this.originalFilters.createBy];
      this.jContacts = [...this.originalFilters.jContacts];
      this.jCRoles = [...this.originalFilters.jCRoles];
      this.jCPartys = [...this.originalFilters.jCPartys];
      this.jCCompanies = [...this.originalFilters.jCCompanies];
      this.IsContactNote = this.originalFilters.IsContactNote;
      this.jTasks = [...this.originalFilters.jTasks];
      this.IsTaskDesc = this.originalFilters.IsTaskDesc;
      this.jTShared = [...this.originalFilters.jTShared];
      this.jTStatus = [...this.originalFilters.jTStatus];
      this.jTPriority = [...this.originalFilters.jTPriority];
      this.dTDate = this.originalFilters.dTDate;
      this.IsNote = this.originalFilters.IsNote;
      this.IsFactlink = this.originalFilters.IsFactlink;
      this.IsComment = this.originalFilters.IsComment;
    } else {
      this._clearAllFilterInternal();
    }

    this.emitFilterEvent('BACK');
  }

  backupCurrentState() {
    // Create a deep copy of the current filter state for cancel functionality
    this.originalFilters = {
      selectedFilters: [...this.selectedFilters],
      jClaims: [...this.jClaims],
      jIssues: [...this.jIssues],
      jRels: [...this.jRels],
      jImps: [...this.jImps],
      jDate: this.jDate ? { ...this.jDate } : null,
      jFiletypes: [...this.jFiletypes],
      jLevels: this.jLevels,
      jFilters: this.jFilters,
      jStatus: [...this.jStatus],
      createDate: this.createDate ? { ...this.createDate } : { start: '', end: '' },
      createBy: [...this.createBy],
      jContacts: [...this.jContacts],
      jCRoles: [...this.jCRoles],
      jCPartys: [...this.jCPartys],
      jCCompanies: [...this.jCCompanies],
      IsContactNote: this.IsContactNote,
      jTasks: [...this.jTasks],
      IsTaskDesc: this.IsTaskDesc,
      jTShared: [...this.jTShared],
      jTStatus: [...this.jTStatus],
      jTPriority: [...this.jTPriority],
      dTDate: this.dTDate,
      IsNote: this.IsNote,
      IsFactlink: this.IsFactlink,
      IsComment: this.IsComment
    };
  }
  
  clearAllFilter() {
    this._clearAllFilterInternal();
  }

  private _clearAllFilterInternal() {
    this.selectedFilters = [];
    this.jClaims = [];
    this.jIssues = [];
    this.jRels = [];
    this.jImps = [];
    this.jDate = null;
    this.jFiletypes = [];
    this.jLevels = null;
    this.jFilters = null;
    this.jStatus = [];
    this.createDate = { start: '', end: '' };
    this.createBy = [];
    this.jContacts = [];
    this.jCRoles = [];
    this.jCPartys = [];
    this.jCCompanies = [];
    this.IsContactNote = false;
    this.jTasks = [];
    this.IsTaskDesc = false;
    this.jTShared = [];
    this.jTStatus = [];
    this.jTPriority = [];
    this.dTDate = null;
    this.IsNote = false;
    this.IsFactlink = false;
    this.IsComment = false;
    this.emitFilterEvent('FILTER', []);
  }
}